const exact = ( (2n ** 61n) - 17n ) * 3n;
const asNumber = (Number(2n ** 61n) - 17) * 3;
console.log(JSON.stringify({ exact: exact.toString(), asNumber: asNumber.toString(), numberIsExact: BigInt(asNumber) === exact }));

const a = 2n ** 61n - 17n;
const result = a * 3n;
console.log("a = " + a.toString());
console.log("result = " + result.toString());
console.log("Number(result) = " + Number(result).toString());
console.log("Number precision check: Number(a) exact? " + (BigInt(Number(a)) === a));

